// <script> 껍데기를 벗긴 알맹이. next/script 로 실어야 클라이언트 이동 때도 함수가 산다.
export const INTRO_SCRIPT = "// 재료 탭. 원본에 이 함수가 없어서 버튼을 눌러도 아무 일도 일어나지 않았다.\nfunction switchIng(btn, key) {\n  var tabs = btn.parentElement.querySelectorAll('.ing-tab');\n  for (var i = 0; i < tabs.length; i++) tabs[i].classList.remove('active');\n  btn.classList.add('active');\n  var keys = ['beef', 'chicken', 'pork'];\n  for (var j = 0; j < keys.length; j++) {\n    var el = document.getElementById('ing-' + keys[j]);\n    if (el) el.style.display = (keys[j] === key) ? 'flex' : 'none';\n  }\n}";
